import openpyxl
wb = openpyxl.load_workbook('output.xlsx')
ws = wb['RNM']

rows = []
for r in range(2, 21):
    vals = [ws.cell(r,c).value for c in range(1,12)]
    if vals[0] is None and vals[1] is None:
        break
    rows.append(vals)

seen = {}
for vals in rows:
    key = (vals[1], vals[2])
    if key in seen:
        seen[key][9] += vals[9]
    else:
        seen[key] = list(vals)

result = []
used = set()
for vals in rows:
    key = (vals[1], vals[2])
    if key not in used:
        result.append(seen[key])
        used.add(key)

for r in range(2, 21):
    for c in range(1, 12):
        ws.cell(r, c).value = None

for i, vals in enumerate(result):
    for c, v in enumerate(vals, start=1):
        ws.cell(2+i, c).value = v

wb.save('output.xlsx')
print('done, wrote', len(result), 'rows')
